package com.example.rokidgeminisecretary;
import android.content.*;import android.net.Uri;import android.os.Build;import android.provider.MediaStore;import android.database.Cursor;import android.media.MediaMetadataRetriever;import android.util.Base64;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.MessageDigest;import java.util.*;import java.util.concurrent.*;
/** One persisted Veo operation. Video chunks are encrypted independently to bound memory use. */
final class VideoGeneration {
 static final String MODEL="veo-3.1-fast-generate-preview";
 static final int MAX_VIDEO=32000000,CHUNK=262144;
 private static final ScheduledExecutorService WORK=Executors.newSingleThreadScheduledExecutor();
 private static boolean initialized,busy;private static JSONArray cache;
 static final class Failure extends IOException{final String diagnostic;Failure(String s){this(s,"");}Failure(String s,String diagnostic){super(s);this.diagnostic=diagnostic;}}
 static File root(Context c){File f=new File(c.getFilesDir(),"generated-videos");f.mkdirs();return f;}
 static File file(Context c,String id,String suffix)throws Exception{if(!id.matches("[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}"))throw new Failure("動画IDが無効です");return new File(root(c),id+suffix);}
 static String chunk(int i){return String.format(Locale.US,".part%03d.gcm",i);}
 static synchronized void save(Context c,JSONObject j)throws Exception{ImageGeneration.encrypted(file(c,j.getString("id"),".json.gcm"),j.toString().getBytes(StandardCharsets.UTF_8));cache=null;}
 static JSONObject read(Context c,String id)throws Exception{return new JSONObject(new String(ImageGeneration.decrypted(file(c,id,".json.gcm")),StandardCharsets.UTF_8));}
 static boolean active(String state){return Arrays.asList("queued","submitting","running","downloading","saving").contains(state);}
 static JSONObject publicRecord(JSONObject j)throws Exception{JSONObject out=new JSONObject();for(String k:new String[]{"id","time","prompt","state","error","statusError","galleryError","galleryUri","sourceImageId","selfReferenceCount","durationMs","width","height","bytes","sha256","aspectRatio","model"})if(j.has(k))out.put(k,j.get(k));out.put("canResume",j.has("operation")&&("paused".equals(j.optString("state"))));return out;}
 static synchronized JSONArray list(Context c)throws Exception{if(cache!=null)return new JSONArray(cache.toString());ArrayList<JSONObject> all=new ArrayList<>();File[] files=root(c).listFiles();if(files!=null)for(File f:files)if(f.getName().endsWith(".json.gcm"))try{all.add(read(c,f.getName().substring(0,36)));}catch(Exception ignored){}all.sort((a,b)->Long.compare(b.optLong("time"),a.optLong("time")));JSONArray result=new JSONArray();for(JSONObject j:all)result.put(publicRecord(j));cache=result;return new JSONArray(result.toString());}
 static JSONObject status(Context c,String id)throws Exception{return publicRecord(read(c,id));}
 static String latest(Context c){try{JSONArray a=list(c);return a.length()==0?"":a.getJSONObject(0).getString("id");}catch(Exception e){return "";}}
 static synchronized void recover(Context raw){if(initialized)return;initialized=true;Context c=raw.getApplicationContext();File[] files=root(c).listFiles();if(files==null)return;for(File f:files)if(f.getName().endsWith(".json.gcm"))try{JSONObject j=read(c,f.getName().substring(0,36));String state=j.optString("state");if("submitting".equals(state)&&!j.has("operation")){j.put("state","error").put("error","アプリ終了で動画の受付結果を確認できません。重複課金を避けるため自動再生成していません");save(c,j);}else if(active(state)){if(busy){j.put("state","paused").put("statusError","別の動画の処理が終わってから結果確認を再開してください");save(c,j);}else{busy=true;String id=j.getString("id");WORK.execute(()->step(c,id));}}else if("completed".equals(state)&&!j.has("galleryUri")&&!j.has("galleryError")){try{gallery(c,j.getString("id"));}catch(Exception e){j.put("galleryError","ロキ内に保存済みです。ギャラリー保存を再試行してください");save(c,j);}}}catch(Exception ignored){}}
 static synchronized JSONObject enqueue(Context raw,String requestId,String prompt,byte[] input,String parent)throws Exception{
  Context c=raw.getApplicationContext();recover(c);prompt=prompt.trim();parent=parent==null?"":parent;if(!requestId.matches("[a-zA-Z0-9-]{8,100}")||prompt.isEmpty()||prompt.length()>1200||prompt.contains("__LOKI_")||prompt.contains("__CODEX_"))throw new Failure("動画の指示は1〜1200文字で入力してください");
  if(input!=null&&input.length>ImageQuestions.MAX_IMAGE)throw new Failure("元画像が大きすぎます");if(input!=null&&!parent.isEmpty())throw new Failure("添付画像と生成画像の元は同時指定できません");
  String id=UUID.nameUUIDFromBytes(requestId.getBytes(StandardCharsets.UTF_8)).toString(),inputHash=input==null?"":RecorderPhotoStore.hash(input);
  if(file(c,id,".json.gcm").exists()){JSONObject old=read(c,id);if(!prompt.equals(old.getString("prompt"))||!inputHash.equals(old.optString("inputHash"))||!parent.equals(old.optString("requestParent")))throw new Failure("同じ送信IDの内容が変わりました");return new JSONObject().put("queued",true).put("videoGenerated",true).put("duplicate",true).put("id",id).put("state",old.getString("state"));}
  if(busy)throw new Failure("動画を生成中です。完成してから次の動画を依頼してください。会話は続けられます");long total=0;int count=0;for(File f:root(c).listFiles()){total+=f.length();if(f.getName().endsWith(".json.gcm"))count++;}if(count>=20||total>256000000L)throw new Failure("動画の保存上限です。生成動画一覧から不要なロキ内コピーを削除してください");
  JSONObject mediaContext=input==null&&parent.isEmpty()?MediaGenerationContext.continuation(c,prompt):new JSONObject();boolean self=LokiSelfProfile.refers(prompt)||mediaContext.optBoolean("self");String chosen=parent;if(input==null&&chosen.isEmpty()&&mediaContext.optString("kind").equals("IMAGE")&&!self)chosen=mediaContext.getString("id");if(input==null&&chosen.isEmpty()&&mediaContext.length()==0&&VideoGenerationPolicy.usesImage(prompt))chosen=ImageGeneration.latest(c);String mime="image/jpeg";
  if(!chosen.isEmpty()){JSONObject image=ImageGeneration.read(c,chosen);if(!"completed".equals(image.optString("state")))throw new Failure("元画像がまだ完成していません");input=ImageGeneration.image(c,chosen,false);mime=image.getString("mime");}
  if(input==null&&mediaContext.length()==0&&VideoGenerationPolicy.usesImage(prompt))throw new Failure("元画像がありません。画像を添付するか、生成画像の「この画像を動画に」を選んでください");
  if(input!=null)ImageGeneration.encrypted(file(c,id,".input.gcm"),input);
  JSONObject j=new JSONObject().put("id",id).put("time",System.currentTimeMillis()).put("prompt",prompt).put("requestParent",parent).put("sourceImageId",chosen).put("inputHash",inputHash).put("hasInput",input!=null).put("inputMime",mime).put("aspectRatio",VideoGenerationPolicy.aspect(prompt,self)).put("state","queued").put("model",MODEL).put("selfSubject",self);if(mediaContext.length()>0){j.put("generationPrompt",MediaGenerationContext.prompt(mediaContext,prompt));if(mediaContext.getString("kind").equals("VIDEO"))j.put("contextVideoId",mediaContext.getString("id"));}save(c,j);busy=true;MainActivity.addAiLog("動画生成: 受付しました。完成まで会話を続けられます。 "+prompt);WORK.execute(()->step(c,id));return new JSONObject().put("queued",true).put("videoGenerated",true).put("id",id).put("state","queued");
 }
 static JSONObject request(Context c,JSONObject job)throws Exception{
  String prompt=job.optString("generationPrompt",job.getString("prompt"));boolean self=job.optBoolean("selfSubject")||LokiSelfProfile.refers(prompt);JSONObject instance=new JSONObject().put("prompt",(self?LokiSelfProfile.FACTS+" 登録画像と同じ一人のロキを、指示がなければ同じ白黒インク画と黒背景で描いてください。 ":"")+prompt);
  if(job.optBoolean("hasInput")){byte[] image=ImageGeneration.decrypted(file(c,job.getString("id"),".input.gcm"));instance.put("image",new JSONObject().put("mimeType",job.getString("inputMime")).put("bytesBase64Encoded",Base64.encodeToString(image,Base64.NO_WRAP)));}
  else if(job.has("contextVideoId")&&!self){byte[] frame=referenceFrame(c,job.getString("contextVideoId"));instance.put("image",new JSONObject().put("mimeType","image/jpeg").put("bytesBase64Encoded",Base64.encodeToString(frame,Base64.NO_WRAP)));}
  else if(self){JSONArray refs=LokiSelfProfile.referenceParts(c),out=new JSONArray();for(int i=0;i<refs.length();i++)if(refs.getJSONObject(i).has("inlineData"))out.put(new JSONObject().put("image",new JSONObject().put("mimeType",refs.getJSONObject(i).getJSONObject("inlineData").getString("mimeType")).put("bytesBase64Encoded",refs.getJSONObject(i).getJSONObject("inlineData").getString("data"))).put("referenceType","ASSET"));instance.put("referenceImages",out);job.put("selfReferenceCount",out.length());}
  JSONObject params=new JSONObject().put("sampleCount",1).put("durationSeconds",8).put("resolution","720p").put("aspectRatio",job.getString("aspectRatio"));if(self||job.optBoolean("hasInput")||job.has("contextVideoId"))params.put("personGeneration","allow_adult");return new JSONObject().put("instances",new JSONArray().put(instance)).put("parameters",params);
 }
 static byte[] referenceFrame(Context c,String id)throws Exception{JSONObject j=read(c,id);if(!"completed".equals(j.optString("state")))throw new Failure("元の動画がまだ完成していません");File temp=new File(c.getCacheDir(),"loki-video-reference-"+id+".mp4");MediaMetadataRetriever retriever=new MediaMetadataRetriever();try{try(OutputStream out=new FileOutputStream(temp)){writeVideo(c,id,out);}retriever.setDataSource(temp.getAbsolutePath());int w=j.optInt("width",640),h=j.optInt("height",640);float scale=Math.min(1f,640f/Math.max(w,h));android.graphics.Bitmap frame=retriever.getScaledFrameAtTime(0,MediaMetadataRetriever.OPTION_CLOSEST_SYNC,Math.max(1,Math.round(w*scale)),Math.max(1,Math.round(h*scale)));if(frame==null)throw new Failure("元動画の参照画像を取得できません");try{ByteArrayOutputStream b=new ByteArrayOutputStream();frame.compress(android.graphics.Bitmap.CompressFormat.JPEG,92,b);if(b.size()>ImageQuestions.MAX_IMAGE)throw new Failure("元動画の参照画像が大きすぎます");return b.toByteArray();}finally{frame.recycle();}}finally{retriever.release();temp.delete();}}
 static boolean operationValid(String name){return name!=null&&name.matches("(?:models/[a-z0-9.-]+/)?operations/[a-zA-Z0-9_-]{1,200}");}
 static JSONObject api(Context c,String path,JSONObject body)throws Exception{
  String key=GeminiCredentialStore.read(c);if(key.isEmpty())throw new Failure("スマホのGemini APIキーを設定してください");HttpURLConnection conn=(HttpURLConnection)new URL("https://generativelanguage.googleapis.com/v1beta/"+path).openConnection();conn.setInstanceFollowRedirects(false);try{conn.setConnectTimeout(15000);conn.setReadTimeout(45000);conn.setRequestProperty("x-goog-api-key",key);if(body!=null){conn.setRequestMethod("POST");conn.setDoOutput(true);conn.setRequestProperty("Content-Type","application/json; charset=utf-8");try(OutputStream out=conn.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}}int status=conn.getResponseCode();if(status!=200)throw httpFailure(conn,status,key,status==403?"動画APIの利用権限・課金設定をGoogle AI Studioで確認してください（HTTP 403）":status==404?"このAPIキーで設定した動画モデルを利用できません（HTTP 404）":status==429?"動画APIの利用上限です。自動再生成はしていません（HTTP 429）":status==400?"動画APIが送信形式を受け付けませんでした（HTTP 400）。自動再生成はしていません":"動画APIが応答エラーです（HTTP "+status+"）。自動再生成はしていません");ByteArrayOutputStream b=new ByteArrayOutputStream();try(InputStream in=conn.getInputStream()){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(b.size()+n>1000000)throw new Failure("動画APIの応答が大きすぎます");b.write(buf,0,n);}}return new JSONObject(b.toString("UTF-8"));}finally{conn.disconnect();}}
 static Failure httpFailure(HttpURLConnection conn,int status,String key,String message){String detail="HTTP "+status;try(InputStream in=conn.getErrorStream()){if(in!=null){ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buf=new byte[1024];int n;while(b.size()<8192&&(n=in.read(buf,0,Math.min(buf.length,8192-b.size())))!=-1)b.write(buf,0,n);JSONObject error=new JSONObject(b.toString("UTF-8")).optJSONObject("error");if(error!=null){String s=error.optString("message").replace(key,"[REDACTED]").replaceAll("[A-Za-z0-9+/=_-]{180,}","[data]");detail+=" "+s.substring(0,Math.min(1600,s.length()));}}}catch(Exception ignored){}return new Failure(message,detail);}
 static String videoUri(JSONObject operation)throws Exception{
  if(operation.has("error"))throw new Failure("動画生成APIが処理を完了できませんでした（コード "+operation.getJSONObject("error").optInt("code")+")。自動再生成はしていません");JSONObject response=operation.optJSONObject("response"),video=response==null?null:response.optJSONObject("generateVideoResponse");if(video==null)throw new Failure("動画生成の完了結果を読み取れません。自動再生成はしていません");JSONArray samples=video.optJSONArray("generatedSamples");if(samples==null||samples.length()!=1){if(video.optInt("raiMediaFilteredCount")>0)throw new Failure(ContentRestrictionPolicy.message("動画生成","CONTENT"));throw new Failure("APIから動画が返りませんでした。自動再生成はしていません");}return samples.getJSONObject(0).getJSONObject("video").getString("uri");
 }
 static URL allowedDownload(String uri)throws Exception{URL u=new URL(uri);String host=u.getHost();if(!u.getProtocol().equals("https")||u.getUserInfo()!=null||u.getRef()!=null||(u.getPort()!=-1&&u.getPort()!=443)||!(host.equals("generativelanguage.googleapis.com")||host.equals("storage.googleapis.com")||host.endsWith(".googleusercontent.com")))throw new Failure("動画の取得先が許可されたGoogle配信先ではありません");return u;}
 static HttpURLConnection downloadConnection(Context c,String uri)throws Exception{URL u=allowedDownload(uri);for(int i=0;i<4;i++){HttpURLConnection conn=(HttpURLConnection)u.openConnection();conn.setInstanceFollowRedirects(false);conn.setConnectTimeout(15000);conn.setReadTimeout(60000);if(u.getHost().equals("generativelanguage.googleapis.com"))conn.setRequestProperty("x-goog-api-key",GeminiCredentialStore.read(c));int status=conn.getResponseCode();if(status>=300&&status<400){String redirect=conn.getHeaderField("Location");conn.disconnect();if(redirect==null)throw new Failure("動画の取得先が不明です");u=allowedDownload(new URL(u,redirect).toString());continue;}if(status!=200){conn.disconnect();throw new Failure("完成動画のダウンロードに失敗しました（HTTP "+status+")。結果確認を再開できます");}if(conn.getContentLengthLong()>MAX_VIDEO){conn.disconnect();throw new Failure("生成動画が保存サイズ上限を超えています");}return conn;}throw new Failure("動画の転送先が多すぎます");}
 static void clearParts(Context c,String id)throws Exception{for(int i=0;i<128;i++){File f=file(c,id,chunk(i));if(f.exists()&&!f.delete())throw new Failure("動画の一時データを整理できません");}}
 static String hex(byte[] bytes){StringBuilder h=new StringBuilder();for(byte b:bytes)h.append(String.format(Locale.US,"%02x",b));return h.toString();}
 static void download(Context c,JSONObject job,String uri)throws Exception{String id=job.getString("id");clearParts(c,id);job.put("state","downloading");save(c,job);HttpURLConnection conn=downloadConnection(c,uri);int total=0,count=0;MessageDigest hash=MessageDigest.getInstance("SHA-256");try(InputStream in=conn.getInputStream()){byte[] buf=new byte[CHUNK];while(true){int used=0,n;while(used<buf.length&&(n=in.read(buf,used,buf.length-used))!=-1)used+=n;if(used==0)break;total+=used;if(total>MAX_VIDEO||count>=128)throw new Failure("生成動画が保存サイズ上限を超えています");if(count==0&&(used<12||buf[4]!='f'||buf[5]!='t'||buf[6]!='y'||buf[7]!='p'))throw new Failure("APIからMP4動画が返りませんでした");byte[] part=used==buf.length?buf:Arrays.copyOf(buf,used);hash.update(part);ImageGeneration.encrypted(file(c,id,chunk(count++)),part);if(used<buf.length)break;}}finally{conn.disconnect();}if(total==0)throw new Failure("完成動画が空です");job.put("bytes",total).put("chunks",count).put("sha256",hex(hash.digest())).put("state","saving");save(c,job);}
 static void writeVideo(Context c,String id,OutputStream out)throws Exception{JSONObject job=read(c,id);int count=job.optInt("chunks"),total=0;if(count<1||count>128||job.optInt("bytes")<1||job.optInt("bytes")>MAX_VIDEO)throw new Failure("保存動画の情報が不正です");MessageDigest hash=MessageDigest.getInstance("SHA-256");for(int i=0;i<count;i++){byte[] part=ImageGeneration.decrypted(file(c,id,chunk(i)));if(part.length>CHUNK||part.length<1)throw new Failure("保存動画の区間が不正です");total+=part.length;hash.update(part);out.write(part);}if(total!=job.getInt("bytes")||!hex(hash.digest()).equals(job.getString("sha256")))throw new Failure("保存動画のハッシュが一致しません");}
 static synchronized Uri gallery(Context c,String id)throws Exception{
  if(Build.VERSION.SDK_INT<29)throw new Failure("ギャラリー保存にはAndroid 10以降が必要です");JSONObject job=read(c,id);String name="Loki-video-"+id+".mp4",path="Movies/Loki/Generated/";Uri collection=MediaStore.Video.Media.EXTERNAL_CONTENT_URI,uri=null;
  try(Cursor cur=c.getContentResolver().query(MediaStore.setIncludePending(collection),new String[]{"_id","is_pending"},"_display_name=? AND relative_path=? AND owner_package_name=?",new String[]{name,path,c.getPackageName()},"_id DESC")){if(cur!=null&&cur.moveToFirst()){uri=ContentUris.withAppendedId(collection,cur.getLong(0));if(cur.getInt(1)==0){job.put("galleryUri",uri.toString());job.remove("galleryError");save(c,job);return uri;}}}
  ContentValues v=new ContentValues();v.put(MediaStore.Video.Media.DISPLAY_NAME,name);v.put(MediaStore.Video.Media.MIME_TYPE,"video/mp4");v.put(MediaStore.Video.Media.RELATIVE_PATH,path);v.put(MediaStore.Video.Media.IS_PENDING,1);if(uri==null)uri=c.getContentResolver().insert(collection,v);if(uri==null)throw new Failure("動画の保存先を作成できません");try{
   try(OutputStream out=c.getContentResolver().openOutputStream(uri,"rwt")){if(out==null)throw new Failure("動画を保存できません");writeVideo(c,id,out);}MessageDigest hash=MessageDigest.getInstance("SHA-256");try(InputStream in=c.getContentResolver().openInputStream(uri)){if(in==null)throw new Failure("動画の保存を検証できません");byte[] buf=new byte[65536];int n;while((n=in.read(buf))!=-1)hash.update(buf,0,n);}if(!hex(hash.digest()).equals(job.getString("sha256")))throw new Failure("ギャラリー動画のハッシュが一致しません");
   MediaMetadataRetriever retriever=new MediaMetadataRetriever();try{retriever.setDataSource(c,uri);long duration=Long.parseLong(retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION));int width=Integer.parseInt(retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_WIDTH)),height=Integer.parseInt(retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_HEIGHT));if(duration<1000||duration>15000||width<1||height<1||width>4096||height>4096)throw new Failure("生成動画の長さ・形式が対応範囲外です");job.put("durationMs",duration).put("width",width).put("height",height);}finally{retriever.release();}
   v.clear();v.put(MediaStore.Video.Media.IS_PENDING,0);if(c.getContentResolver().update(uri,v,null,null)!=1)throw new Failure("動画の保存公開に失敗しました");job.put("galleryUri",uri.toString());job.remove("galleryError");save(c,job);return uri;
  }catch(Exception e){c.getContentResolver().delete(uri,null,null);throw e;}
 }
 static void completed(Context c,JSONObject job)throws Exception{String id=job.getString("id");job.put("state","completed");job.remove("statusError");save(c,job);try{gallery(c,id);}catch(Exception e){job=read(c,id);job.put("galleryError","ロキ内に動画は保存済みです。ギャラリー保存を再試行してください");save(c,job);}file(c,id,".input.gcm").delete();MainActivity.addAiLog("動画生成: 完成しました。会話のそばの生成動画一覧から再生・保存できます。");MainActivity.queueBridgeCommand(c,"__LOKI_VIDEO__:"+id,true);synchronized(VideoGeneration.class){busy=false;}}
 static void step(Context c,String id){JSONObject job=null;try{job=read(c,id);String state=job.getString("state");if("saving".equals(state)){completed(c,job);return;}
  if("queued".equals(state)){JSONObject body=request(c,job);job.put("state","submitting");save(c,job);JSONObject receipt=api(c,"models/"+MODEL+":predictLongRunning",body);String name=receipt.optString("name");if(!operationValid(name))throw new Failure("動画APIの受付IDを確認できません。自動再生成はしていません");job.put("operation",name).put("state","running");save(c,job);file(c,id,".input.gcm").delete();}
  String operation=job.optString("operation");if(!operationValid(operation))throw new Failure("動画APIの受付IDが無効です。自動再生成はしていません");if(System.currentTimeMillis()-job.getLong("time")>36*60*60*1000L)throw new Failure("動画APIの結果保存期間を超えた可能性があります。自動再生成はしていません");
  JSONObject result=api(c,operation,null);if(result.optBoolean("done")){String uri=videoUri(result);download(c,job,uri);completed(c,job);return;}
  if(System.currentTimeMillis()-job.optLong("pollStarted",job.getLong("time"))>20*60*1000L){job.put("state","paused").put("statusError","結果待ちが長いため確認を休止しています。「結果確認を再開」で同じ受付IDを確認できます");save(c,job);synchronized(VideoGeneration.class){busy=false;}return;}
  job.put("state","running");job.remove("statusError");save(c,job);WORK.schedule(()->step(c,id),10,TimeUnit.SECONDS);
 }catch(Exception e){try{if(job==null)job=read(c,id);boolean hasOperation=operationValid(job.optString("operation"));boolean terminal=e instanceof Failure && !("downloading".equals(job.optString("state")));String message=e instanceof Failure?e.getMessage():hasOperation?"動画の結果確認・保存を完了できませんでした。再生成せず結果確認を再開できます":"動画の受付結果を確認できません。重複課金を避けるため自動再生成していません";job.put("state",hasOperation&&!terminal?"paused":"error").put("error",message);if(e instanceof Failure&&!((Failure)e).diagnostic.isEmpty())job.put("diagnostic",((Failure)e).diagnostic);save(c,job);MainActivity.addAiLog("動画生成: "+message);if(!hasOperation)file(c,id,".input.gcm").delete();MainActivity.queueBridgeCommand(c,"__LOKI_VIDEO__:"+id,true);}catch(Exception ignored){}synchronized(VideoGeneration.class){busy=false;}}}
 static synchronized void resume(Context c,String id)throws Exception{recover(c);JSONObject j=read(c,id);if(!"paused".equals(j.optString("state"))||!operationValid(j.optString("operation")))throw new Failure("結果確認を再開できる受付IDがありません。自動再生成はしません");if(busy)throw new Failure("別の動画を処理中です");j.put("state","running").put("pollStarted",System.currentTimeMillis());j.remove("error");j.remove("statusError");save(c,j);busy=true;WORK.execute(()->step(c.getApplicationContext(),id));}
 static synchronized void delete(Context c,String id)throws Exception{JSONObject j=read(c,id);if(active(j.optString("state")))throw new Failure("生成中の動画は削除できません");clearParts(c,id);for(String suffix:new String[]{".input.gcm",".json.gcm"}){File f=file(c,id,suffix);if(f.exists()&&!f.delete())throw new Failure("削除を確認できません");}cache=null;}
 private VideoGeneration(){}
}
